	SUBROUTINE KTABLE(NAM1,ANS,FMIN9,INDEX)
	INTEGER*2 CODE,RND,BINDEX,D,SUMK,AK,GETMO,GETDAY,J,
     *INDEX,MAG,NK,IYR,IYJ,JD,MO,NPARM(4)
	REAL*4 SAK,DK,V,FMIN9,FPARM(4)
	CHARACTER ANS*1,ID*2,ISN*24,APARM*26
	CHARACTER*9 GETMOL,MOL
	CHARACTER*12 NAM1,NAM2,NAM3
	DIMENSION INDEX(9),BINDEX(10),MAG(8),
     1DK(8)
	COMMON/OBSYDAT/FPARM,IPARM,APARM,NPARM
      DATA BINDEX/0,3,7,15,30,48,80,140,240,400/
C
	ISW1=0                              !Switch for table header
	OPEN(UNIT=*,CARRIAGE CONTROL='FORTRAN')
	CALL EXNAM(NAM1,NAM2,'.DIG')
      CALL EXNAM(NAM1,NAM3,'.DKA')
	ID=NAM1(1:2)
	CALL OINFO(1,ID,'FN')
	DO I=1,25
	  ISN(I:I)=APARM(I:I)
	ENDDO
	OPEN(UNIT=3,FILE=NAM2,STATUS='OLD')
	OPEN(UNIT=2,FILE=NAM3,STATUS='UNKNOWN',
     *CARRIAGE CONTROL='FORTRAN',FORM='FORMATTED')
   10 READ(3,2000,END=888)IYJ,(MAG(I),I=1,8)
 2000 FORMAT(I6,4(I6,24X),/,6X,4(I6,24X))
      NK=0
      SAK=0.
      SUMK=0
      IYR=IYJ/1000
      JD=IYJ-(IYR*1000)
      MO=GETMO(IYR+70,JD)
	D=GETDAY(IYR+70,JD)
	IF(ISW1.NE.0)GOTO 25
	MOL=GETMOL(MO)
C*** WRITE STATION NAME AND LOCATION, TIME, AND TABLE HEADER INFORMATION
	IF(ANS.EQ.'Y')THEN
	  WRITE(2,3001)ISN
 3001   FORMAT(///5X,A24,3X,'PRELIMINARY K VALUES')
	ELSE
        WRITE(2,3000)ISN
 3000   FORMAT(///5X,A24)
	ENDIF
      WRITE(2,3005)MOL,(IYR+1970)
 3005 FORMAT(5X,A9,I4)
      WRITE(2,3010)
 3010 FORMAT(5X,'MODAYR  JULIAN   0    3    6    9',
     *'     12   15   18   21HOUR  KSUM    AK')
      WRITE(2,3015)
 3015 FORMAT(13X,'DAY')
      WRITE(2,3020)
 3020 FORMAT(' ')
	ISW1=1
   25 WRITE(2,1000)MO,D,(IYR+70),JD
 1000 FORMAT(5X,3(I2),2X,I3,2X)
      DO 60 I=1,8
      IF(MAG(I).LE.6000)GOTO 30
      DK(I)=99.9
      GOTO 60
   30 V=MAG(I)
      DK(I)=RKV(V,FMIN9,INDEX,J)
      IF(DK(I).EQ.99.9)GOTO 60
      NK=NK+1
      J=INT(DK(I))
      SAK=SAK+BINDEX(J+1)
      SUMK=SUMK+J
   60 CONTINUE
      WRITE(2,1010)(DK(I),I=1,8)
 1010 FORMAT('&',2X,(4F5.1,2X,4F5.1))
      IF(NK.GE.8)GOTO 65
      SUMK=999
      AK=999
      GOTO 70
   65 A=SAK/NK
      AK=RND(A)
   70 WRITE(2,1020)SUMK,AK
 1020 FORMAT('&',2X,I6,2X,I6)
      CODE=MOD(D,5)
      IF(CODE.NE.0)GOTO 85
      WRITE(2,1030)
 1030 FORMAT(' ')
   85 CONTINUE
      GOTO 10
  888 CLOSE(UNIT=3)
C      CLOSE(UNIT=3,STATUS='DELETE')
      CLOSE(UNIT=2)
      STOP
      END
